import sys

def find_permutation(n, p):
    q = [-1] * n
    visited = [False] * n

    for i in range(n):
        if not visited[i]:
            cycle = []
            x = i
            while not visited[x]:
                visited[x] = True
                cycle.append(x)
                x = p[x] - 1

            m = len(cycle)
            if m % 2 == 1:
                mid = cycle[m // 2]
                q[mid] = mid + 1
                for j in range(m // 2):
                    q[cycle[j]] = cycle[m - j - 1] + 1
                    q[cycle[m - j - 1]] = cycle[j] + 1
            else:
                for j in range(m // 2):
                    q[cycle[j * 2]] = cycle[j * 2 + 1] + 1
                    q[cycle[j * 2 + 1]] = cycle[j * 2] + 1

    if -1 in q:
        return -1
    return q

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    p = list(map(int, input[1:]))
    result = find_permutation(n, p)
    if result == -1:
        print(-1)
    else:
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
